package com.bank.stack;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class ArrayDequeStackTest {

    @Test
    void push_pop_peek_lifo() {
        Deque<String> stack = new ArrayDeque<>();
        stack.push("UNDO-1");
        stack.push("UNDO-2");
        stack.push("UNDO-3");

        assertThat(stack.peek()).isEqualTo("UNDO-3");  // top
        assertThat(stack.pop()).isEqualTo("UNDO-3");   // LIFO!
        assertThat(stack.pop()).isEqualTo("UNDO-2");
        assertThat(stack.pop()).isEqualTo("UNDO-1");
        assertThat(stack).isEmpty();
    }

    @Test
    void legacyStack_allowsRandomAccess() {
        Stack<String> stack = new Stack<>();
        stack.push("A"); stack.push("B"); stack.push("C");
        assertThat(stack.get(0)).isEqualTo("A");  // random access! Bad stack!
        // ArrayDeque does NOT have get(index) — proper LIFO only!
    }

    @Test
    void noNullAllowed() {
        Deque<String> stack = new ArrayDeque<>();
        assertThatThrownBy(() -> stack.push(null))
            .isInstanceOf(NullPointerException.class);
    }

    @Test
    void asQueue_fifo() {
        Deque<String> queue = new ArrayDeque<>();
        queue.offer("FIRST"); queue.offer("SECOND"); queue.offer("THIRD");
        assertThat(queue.poll()).isEqualTo("FIRST");  // FIFO!
    }
}
